// LINE Webhook Data Validation & Transform for Supabase
const items = $input.all();
const results = [];

for (const item of items) {
  try {
    const payload = item.json;

    // [VALIDATION] LINE検証リクエスト検出（空配列）
    if (!payload.events || payload.events.length === 0) {
      console.log('[VALIDATION] LINE verification request detected - skipping');
      // shouldStopフラグを設定してワークフローを停止
      return [{ json: { shouldStop: true, reason: 'LINE verification request' } }];
    }

    // [VALIDATION] 必須フィールド確認
    const event = payload.events[0];
    if (!event || !event.type || !event.source || !event.source.userId) {
      throw new Error('Missing required fields in event');
    }

    // [VALIDATION] followイベントのみ処理
    if (event.type !== 'follow') {
      console.log(`[VALIDATION] Skipping non-follow event: ${event.type}`);
      return [{ json: { shouldStop: true, reason: `Non-follow event: ${event.type}` } }];
    }

    // [TRANSFORM] lead_id生成（n8n実行ID + タイムスタンプ）
    const executionId = $execution.id || 'unknown';
    const timestamp = event.timestamp || Date.now();
    const lead_id = `${executionId}-${timestamp}`;

    // [TRANSFORM] タイムスタンプをJST（UTC+9）に変換
    const eventDate = new Date(timestamp);
    const processedDate = new Date();

    // ISO 8601形式でタイムゾーン付き（PostgreSQL TIMESTAMPTZ用）
    const timestamp_jst = eventDate.toISOString();
    const processed_at = processedDate.toISOString();

    // [OUTPUT] Supabase用データ構造
    const transformedData = {
      lead_id: lead_id,
      user_id: event.source.userId,
      display_name: '',  // 後でLINE APIから取得
      picture_url: '',   // 後でLINE APIから取得
      timestamp_jst: timestamp_jst,
      processed_at: processed_at,
      source: 'webhook',
      status: 'pending'
    };

    console.log('[SUCCESS] Data validation and transformation completed');
    console.log('[DATA]', JSON.stringify(transformedData, null, 2));

    results.push({ json: transformedData });

  } catch (error) {
    console.error('[ERROR] Validation failed:', error.message);
    throw error;
  }
}

return results;

// Success Log
const items = $input.all();
const results = [];

for (const item of items) {
  const insertedData = item.json;

  console.log('[SUCCESS] Record inserted into Supabase');
  console.log('[RECORD_ID]', insertedData.id || 'N/A');
  console.log('[USER_ID]', insertedData.user_id || 'N/A');
  console.log('[LEAD_ID]', insertedData.lead_id || 'N/A');

  results.push({
    json: {
      success: true,
      message: 'LINE lead successfully recorded',
      record_id: insertedData.id,
      user_id: insertedData.user_id,
      lead_id: insertedData.lead_id,
      timestamp: new Date().toISOString()
    }
  });
}

return results;

// Error Handler
const error = $input.first().json.error || {};
const executionId = $execution.id || 'unknown';

console.error('[ERROR] Workflow execution failed');
console.error('[EXECUTION_ID]', executionId);
console.error('[ERROR_MESSAGE]', error.message || 'Unknown error');
console.error('[ERROR_STACK]', error.stack || 'No stack trace');

return [{
  json: {
    success: false,
    error: {
      message: error.message || 'Internal server error',
      type: error.name || 'Error',
      execution_id: executionId,
      timestamp: new Date().toISOString()
    }
  }
}];
